window.HOEREN_TESTS[49] = {"id":"beim-tierarzt","name":"Beim Tierarzt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Tier-Besitzer: Die Tierarztpraxis Dr. Schmidt ist nächste Woche geschlossen, die Familie macht Urlaub. Notfälle gehen bitte nicht ins Tier-Krankenhaus, sondern zur Praxis Dr. Müller in der Hauptstraße 12. Die Telefonnummer steht auf unserer Webseite. Ab Montag in einer Woche sind wir wieder da. Vielen Dank für Ihr Verständnis!","gender":"f","q":"Wohin gehen Notfälle?","opts":["Zur Praxis Dr. Schmidt.","Ins Tier-Krankenhaus.","Zur Praxis Dr. Müller."],"correct":2},{"transcript":"Hallo Doktor, hier ist Familie Bauer. Unsere Katze Minka frisst seit zwei Tagen nichts. Sie ist nicht verletzt und sie ist auch nicht weg, sie liegt nur zu Hause. Sie ist sehr müde und schläft viel. Wir möchten einen Termin so bald wie möglich. Bitte rufen Sie zurück, wir können auch heute kommen. Sie ist 8 Jahre alt.","gender":"f","q":"Was ist das Problem?","opts":["Katze ist verletzt.","Katze frisst nicht.","Katze ist weg."],"correct":1},{"transcript":"Achtung Hunde-Besitzer: Eine wichtige Information. Die jährliche Impfung gegen Tollwut ist Pflicht, Floh-Schutz und Wurm-Kur sind empfohlen, aber nicht Pflicht. Wer noch nicht zur Tollwut-Impfung war, kommt bitte bis Ende des Monats. Kosten 45 Euro. Nicht-geimpfte Hunde dürfen nicht in den Park. Bitte achtet darauf. Danke!","gender":"m","q":"Was ist Pflicht?","opts":["Wurm-Kur.","Floh-Schutz.","Tollwut-Impfung."],"correct":2},{"transcript":"Hi Anna, hier ist Markus. Mein Hund Rex hat eine Wunde am Bein und hinkt, er ist verletzt. Bello ist nicht verletzt, ihm geht es gut. Wir gehen jetzt sofort zum Tierarzt. Kannst du bitte eine Stunde auf Bello aufpassen? Ich bringe ihn dann wieder ab. Ruf schnell zurück, danke dir!","gender":"m","q":"Welcher Hund ist verletzt?","opts":["Rex.","Bello.","Beide."],"correct":0},{"transcript":"Liebe Kunden: Unsere Tierarztpraxis hat neue Öffnungszeiten ab nächsten Montag. Statt Montag bis Freitag von 8 bis 18 Uhr sind wir nun bis 20 Uhr offen. Bis 22 Uhr können wir leider nicht bleiben, das Team braucht Pause. Samstag bleibt 9 bis 12 Uhr, Sonntag geschlossen wie bisher. Termin nötig, bitte vorher anrufen.","gender":"f","q":"Bis wann ist die Praxis jetzt offen?","opts":["18 Uhr.","20 Uhr.","22 Uhr."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat welches Tier? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Tierarzt hat diese Woche noch ein paar Termine frei."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Die Tiere können nicht alle am selben Tag kommen."},{"speaker":"Lukas","gender":"m","text":"Ich nehme den Hund mit. Er humpelt seit gestern ein bisschen."},{"speaker":"Lisa","gender":"f","text":"Meine Katze hustet schon die ganze Nacht. Ich bringe sie morgen früh vorbei."},{"speaker":"Lukas","gender":"m","text":"Bringt noch jemand ein Pferd mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Das Pferd bleibt auf dem Hof."},{"speaker":"Lukas","gender":"m","text":"Der Arzt soll die Katze dann genau anschauen. Was ist mit Tom los?"},{"speaker":"Lisa","gender":"f","text":"Tom kommt mit seinem Hamster. Der kleine Kerl braucht dringend Medizin."},{"speaker":"Lukas","gender":"m","text":"Der Arzt gibt ihm dann Tropfen. Kommt Sara auch vorbei?"},{"speaker":"Lisa","gender":"f","text":"Sara bringt die Fische mit. Die haben seltsame Flecken im Glas."},{"speaker":"Lukas","gender":"m","text":"Er schaut sie mit der Lampe an. Nehmen wir eine Schlange auch mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Schlange nehmen wir auch nicht mit."},{"speaker":"Lukas","gender":"m","text":"Was macht Tim?"},{"speaker":"Lisa","gender":"f","text":"Tim hat den Papagei dabei. Der spricht seit ein paar Wochen nicht mehr."},{"speaker":"Lukas","gender":"m","text":"Hoffentlich ist es nichts Schlimmes. Ich schreibe alle Namen auf einen Zettel für den Empfang."},{"speaker":"Lisa","gender":"f","text":"Leg ihn bitte an den Kühlschrank. Morgen früh geht es mit dem Hund los."}],"options":[{"letter":"a","text":"Hamster"},{"letter":"b","text":"Papagei"},{"letter":"c","text":"Pferd"},{"letter":"d","text":"Schildkröte"},{"letter":"e","text":"Hund"},{"letter":"f","text":"Kaninchen"},{"letter":"g","text":"Fische"},{"letter":"h","text":"Schlange"},{"letter":"i","text":"Katze"}],"items":[{"person":"Lukas","correct":"e"},{"person":"Lisa","correct":"i"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Besitzerin","gender":"f","text":"Guten Tag Doktor, was hat meine Katze? Sie niest und ist so müde."},{"speaker":"Tierarzt","gender":"m","text":"Eine kleine Erkältung, nichts Ernstes. Sie braucht ein paar Tage Ruhe."},{"speaker":"Besitzerin","gender":"f","text":"Brauchen wir Medikamente? Tabletten oder Spritzen, wie bei letztes Mal?"},{"speaker":"Tierarzt","gender":"m","text":"Keine Tabletten und keine Spritzen diesmal. Nur Tropfen, drei Tropfen pro Tag ins Futter."},{"speaker":"Besitzerin","gender":"f","text":"Gut, dann Tropfen. Wie lange muss ich das geben?"},{"speaker":"Tierarzt","gender":"m","text":"Fünf Tage, dann kommt sie zur Kontrolle wieder. Das reicht meistens."}],"q":"Was bekommt die Katze?","opts":["Tropfen.","Tabletten.","Spritzen."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, ich brauche einen Impfungs-Termin für unseren Hund, möglichst nächste Woche."},{"speaker":"Sekretärin","gender":"f","text":"Gerne, passt Ihnen Mittwoch oder lieber Freitag? Beide Tage haben wir noch Zeit."},{"speaker":"Vater","gender":"m","text":"Mittwoch muss ich arbeiten, da geht es leider nicht. Dann lieber Freitag."},{"speaker":"Sekretärin","gender":"f","text":"Dann nehmen wir Freitag um 10 Uhr. Ist das okay für Sie?"},{"speaker":"Vater","gender":"m","text":"Ja, Freitag um 10 ist gut. Danke, wir kommen pünktlich mit dem Hund."}],"q":"Wann ist der Termin?","opts":["Freitag.","Mittwoch.","Beides."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Mama, der Hund frisst nicht! Schon den ganzen Tag steht der Napf voll da."},{"speaker":"Mutter","gender":"f","text":"Gib ihm anderes Futter, vielleicht hat er heute keine Lust auf das alte."},{"speaker":"Tochter","gender":"f","text":"Ich habe schon dreimal anderes Futter probiert. Nichts essen will er."},{"speaker":"Mutter","gender":"f","text":"Dann machen wir nichts mehr selbst. Morgen gehen wir zum Tierarzt, das ist sicherer."},{"speaker":"Tochter","gender":"f","text":"Okay, morgen zum Tierarzt. Ich rufe gleich an und frage nach einem Termin."}],"q":"Was wird gemacht?","opts":["Anderes Futter.","Zum Tierarzt.","Nichts."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wie viel kostet die Operation für unseren Hund ungefähr?"},{"speaker":"Tierärztin","gender":"f","text":"Etwa 500 Euro, je nach Komplikation. Nicht 300 und nicht 1000, so in der Mitte."},{"speaker":"Kunde","gender":"m","text":"300 Euro ist wenig, 1000 Euro ist zu viel. Zahlt die Versicherung?"},{"speaker":"Tierärztin","gender":"f","text":"Wenn Sie eine Tier-Versicherung haben, zahlt sie oft 80 Prozent. Bringen Sie die Karte mit."},{"speaker":"Kunde","gender":"m","text":"Gut, dann planen wir mit 500 Euro. Ich habe die Versicherung dabei."}],"q":"Wie viel kostet die Operation?","opts":["300 Euro.","1000 Euro.","500 Euro."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Doktor, ist Rex schon sehr alt? Manche sagen 10 Jahre, manche 15."},{"speaker":"Tierarzt","gender":"m","text":"Rex ist 12 Jahre, für einen Schäferhund schon alt. 10 ist jünger, 15 ist sehr alt."},{"speaker":"Frau","gender":"f","text":"Wie lange hat er noch, denken Sie? Ich mache mir Sorgen."},{"speaker":"Tierarzt","gender":"m","text":"Schwer zu sagen. Ein paar Jahre vielleicht, wenn Sie ihn gut pflegen und nicht zu viel füttern."},{"speaker":"Frau","gender":"f","text":"Okay, 12 Jahre, dann passe ich noch besser auf ihn auf. Danke, Doktor."}],"q":"Wie alt ist Rex?","opts":["10 Jahre.","15 Jahre.","12 Jahre."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Doktor Wagner, einer Tierärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Doktor Wagner, Sie arbeiten als Tierärztin seit 15 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Wagner","gender":"f","text":"Als Kind hatte ich immer Tiere — Hamster, Hund, Pferde später. Wollte zuerst Humanmedizin, war zu wettbewerbsorientiert. Veterinär war meine eigentliche Liebe. Das Studium war lang, aber ich habe keinen Tag bereut. Tiere sind ehrlicher als Menschen, finde ich."},{"speaker":"Reporter","gender":"m","text":"Welche Tiere behandeln Sie meistens?"},{"speaker":"Wagner","gender":"f","text":"Hunde am häufigsten, dann Katzen. Kleintiere wie Hamster und Meerschweinchen seltener — die werden oft nicht behandelt, leider. Vögel manchmal, auch Schildkröten. Pferde mache ich nicht — andere Spezialisierung."},{"speaker":"Reporter","gender":"m","text":"Was ist die häufigste Krankheit?"},{"speaker":"Wagner","gender":"f","text":"Übergewicht! Sehr viele Hunde und Katzen sind zu dick. Besitzer überfüttern aus Liebe. Diabetes, Gelenkprobleme — die Folgen. Auch Zahnprobleme häufig — niemand putzt Hunden die Zähne, sollten aber."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Tier-Besitzern?"},{"speaker":"Wagner","gender":"f","text":"Vorsorge wichtiger als Behandlung. Jährliche Untersuchung, Impfungen. Genug Bewegung — Hunde brauchen Auslauf. Gutes Futter, nicht zu viel. Liebe geben — Tiere fühlen das."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwerste am Beruf?"},{"speaker":"Wagner","gender":"f","text":"Einschläfern. Wenn ein altes Tier muss, weine ich oft mit den Besitzern. Auch wenn ich es schon hundertmal gemacht habe — schwer. Aber besser als langes Leiden. Das müssen Besitzer akzeptieren."}],"items":[{"q":"Frau Doktor Wagner wollte erst Humanmedizin studieren.","correct":"ja"},{"q":"Sie behandelt auch Pferde.","correct":"nein"},{"q":"Übergewicht ist die häufigste Krankheit bei Haustieren.","correct":"ja"},{"q":"Sie rät Tier-Besitzern, weniger zur Vorsorge zu kommen.","correct":"nein"},{"q":"Das Schwerste ist das Einschläfern alter Tiere.","correct":"ja"}]}]};
